import 'package:flutter/material.dart';import '../database/db_helper.dart';import '../models/book.dart';
class LibraryScreen extends StatefulWidget{const LibraryScreen({super.key});@override State<LibraryScreen> createState()=>_LibraryScreenState();}
class _LibraryScreenState extends State<LibraryScreen>{List<Book> books=[];@override void initState(){super.initState();load();}Future<void> load()async{books=await DbHelper.instance.getBooks();if(mounted)setState((){});}Future<void> add()async{final title=TextEditingController(),author=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('افزودن کتاب'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'عنوان کتاب')),TextField(controller:author,decoration:const InputDecoration(labelText:'نویسنده (اختیاری)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ذخیره'))]));if(ok==true&&title.text.trim().isNotEmpty){await DbHelper.instance.createBook(Book(title:title.text.trim(),author:author.text.trim(),createdAt:DateTime.now().toIso8601String()));await load();}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('کتابخانه')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('کتاب جدید')),body:books.isEmpty?const Center(child:Text('کتابی ندارید؛ کتاب تازه اضافه کنید.')):ListView.builder(itemCount:books.length,itemBuilder:(c,i){final b=books[i];return Card(margin:const EdgeInsets.symmetric(horizontal:14,vertical:5),child:ListTile(leading:const CircleAvatar(child:Icon(Icons.menu_book)),title:Text(b.title),subtitle:Text(b.author.isEmpty?'کتاب':b.author),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await DbHelper.instance.deleteBook(b.id!);await load();})));}));}}
